    correctKey: 'B',
    explanation: '夏型（南高北低）の気圧配置は太平洋高気圧が日本の南から張り出し日本付近を広く覆う配置で、晴天・高温をもたらす。冬型とは高気圧・低気圧の位置関係が逆になる。\n\n夏型では太平洋高気圧が日本の南から北西へ張り出し、日本付近を広く覆う。等圧線の間隔は広く風は弱い。高気圧に覆われると下降流で晴天が続き、日射により気温が上がって猛暑となる。梅雨明け後の典型的な配置である。\n\n【図解】冬型と夏型の対比\n　項目｜冬型（西高東低）｜夏型（南高北低）\n　高気圧の位置｜大陸（西）｜太平洋（南）\n　等圧線｜南北の縦じま・狭い｜広くゆるやか\n　天気｜日本海側で雪｜広く晴れて高温\n　⇒ 高気圧と低気圧の位置関係が季節によって入れ替わる\n　⚠ 夏型でシベリア高気圧が覆うとするのは冬型との取り違えである。',
