    question: 'エマグラム上でCAPE（対流有効位置エネルギー）に対応する領域を読み取る方法に関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: '地上付近の空気塊を仮想的に持ち上げた際の気塊の温度変化を示す「気塊の上昇曲線」を状態曲線に重ね、自由対流高度（LFC）から平衡高度（EL）までの間で気塊の上昇曲線が状態曲線（環境の気温）よりも右側（高温側）にある領域の面積が、CAPEに対応する。', explanation: '正しい。CAPEをエマグラム上で読み取るには、まず地上付近の代表的な空気塊を仮想的に持ち上げたときの気温変化（乾燥断熱線に沿って上昇し、持ち上げ凝結高度からは湿潤断熱線に沿って上昇する「気塊の上昇曲線」）を作図し、これを実際の環境の気温を表す状態曲線と比較する。自由対流高度（LFC）から平衡高度（EL）までの間で、気塊の上昇曲線が状態曲線より右側（高温側、つまり気塊の方が周囲より暖かく浮力を持つ）にある領域の面積が、CAPEに対応する部分である。' },
      { key: 'B', text: 'CAPEに対応する領域は、地上から圏界面までのすべての高度で一様に定義される。', explanation: '誤り。CAPEに対応する領域は、自由対流高度（LFC）から平衡高度（EL）までの、気塊が周囲より暖かく（浮力が正に）なる区間に限定されるものであり、地上から圏界面までの全高度で一様に定義されるものではない。' },
      { key: 'C', text: 'CAPEに対応する領域は、気塊の上昇曲線が状態曲線より左側（低温側）にある領域として定義される。', explanation: '誤り。気塊の上昇曲線が状態曲線より左側（低温側、気塊が周囲より冷たい＝負の浮力）にある領域はCIN（対流抑制）に対応する部分であり、CAPEに対応するのは右側（高温側）の領域である。' },
      { key: 'D', text: 'CAPEに対応する領域を読み取るためには、風向風速の情報が必須であり、気温・露点温度の情報だけでは求められない。', explanation: '誤り。CAPEは気塊の上昇曲線（気温変化）と環境の状態曲線（気温）との比較のみから求められる量であり、風向風速の情報は必須ではない（風の情報は主にシアーの評価等、別の診断に用いられる）。' },
    ],
    correctKey: 'A',
    explanation: 'エマグラム上のCAPEは、気塊の上昇曲線がLFCからELの間で状態曲線より右側（高温側）にある領域の面積として読み取る。左側の領域はCINに対応する。\n【図解】\n★ポイント: CAPE＝LFC〜EL間で気塊の上昇曲線が状態曲線より右（高温側）にある領域の面積\n○正: Aの通り、気塊の上昇曲線と状態曲線の位置関係からCAPE・CINを区別して読み取る\n×誤: Bのように全高度で一様とする記述、Cのように左側の領域とする記述、Dのように風の情報が必須とする記述はいずれも誤り\n⚠注意: CAPEの面積が大きいほど積乱雲の発達ポテンシャルが大きいと判断するのが実技の要点\n→ 結論: CAPEのエマグラム上の読み取り方を正確に述べたAが正解（A）',
