    question: '状態曲線の傾き（環境の気温減率）から大気の安定度を判定する実技的な方法に関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: 'エマグラム上で状態曲線の傾きを、乾燥断熱線・湿潤断熱線の傾きと比較することで、その層が絶対安定・絶対不安定・条件付き不安定のいずれの状態にあるかを視覚的に判定することができる。', explanation: '正しい。エマグラムには乾燥断熱線・湿潤断熱線があらかじめ描かれており、実際に観測された状態曲線の傾きをこれらの断熱線の傾きと比較することで、その層の気温減率が乾燥断熱減率より大きい（絶対不安定）か、湿潤断熱減率より小さい（絶対安定）か、その中間（条件付き不安定）かを、計算をせずとも視覚的に判定することができる、実技試験における基本的な安定度判定の方法である。' },
      { key: 'B', text: '状態曲線の傾きが乾燥断熱線と完全に平行であれば、その層は絶対不安定と判定される。', explanation: '誤り。状態曲線が乾燥断熱線と平行（気温減率が乾燥断熱減率と等しい）である場合は「中立」の状態であり、絶対不安定と判定されるのは、状態曲線の傾きが乾燥断熱線よりもさらに急な（気温減率がより大きい）場合である。' },
      { key: 'C', text: '状態曲線の傾きから安定度を判定する方法は、実技試験では用いられず、数値計算のみが用いられる。', explanation: '誤り。エマグラム上での状態曲線と断熱線の傾きの比較による視覚的な安定度判定は、実技試験において基本的かつ重要な技能として求められる方法であり、数値計算のみに限定されるわけではない。' },
      { key: 'D', text: '状態曲線が垂直（高度によらず気温が一定）である場合、その層は絶対不安定と判定される。', explanation: '誤り。状態曲線が垂直に近い（気温がほぼ一定の等温層）場合は、環境減率がほぼゼロであり、これは乾燥断熱減率よりも小さいため、一般に安定（絶対安定に近い）と判定される。' },
    ],
    correctKey: 'A',
    explanation: 'エマグラム上で状態曲線の傾きを乾燥断熱線・湿潤断熱線と比較することで、絶対安定・絶対不安定・条件付き不安定を視覚的に判定できる、実技試験の基本技能。\n【図解】\n★ポイント: 状態曲線の傾き＞乾燥断熱線＝絶対不安定、状態曲線の傾き＜湿潤断熱線＝絶対安定、その中間＝条件付き不安定\n○正: Aの通り、断熱線との傾きの比較で安定度を視覚的に判定するのが実技の基本\n×誤: Bのように平行を不安定とする記述、Dのように等温層を不安定とする記述はいずれも誤り\n→ 結論: 状態曲線の傾きによる安定度判定法を正確に述べたAが正解（A）',
