    id: 'kisho_jitsumu_133',
    subject: 'jitsumu',
    subjectName: '実技試験',
    question: '温暖前線前面の層状雲域の広がりを衛星画像から読み取る方法に関する記述として正しいものはどれか。',
    choices: [
      { key: 'B', text: '温暖前線が接近する際、衛星画像（赤外画像）では前線本体よりかなり前方（東側）まで、次第に雲頂高度が低くなっていく（雲頂温度が高くなっていく）滑らかな広がりを持つ雲域が確認されることが多く、この雲域の広がり方から前線の接近の程度を推測できる。', explanation: '正しい。温暖前線は暖気が寒気の上を緩やかに這い上がる構造のため、前線本体よりかなり前方（進行方向側）まで、まず雲頂の高い巻雲・巻層雲が先行し、前線に近づくにつれて次第に雲頂の低い（雲頂温度が高い）高層雲・乱層雲へと変化する、滑らかに広がる雲域が衛星画像上で確認される。実技試験では、この雲域の広がりのパターンから、前線がどの程度接近しているかを推測することが求められる。' },
      { key: 'A', text: '温暖前線前面の雲域は、衛星画像上では前線通過の直前になって初めて出現する、局所的な雲域である。', explanation: '誤り。温暖前線前面の雲域は、前線本体が到達するかなり前（数百km以上前方）から先行して現れる、広範囲にわたる雲域であり、前線通過の直前に初めて出現する局所的な雲域ではない。' },
      { key: 'C', text: '温暖前線前面の雲域は、積乱雲が孤立して点在するまだら状のパターンを示すことが典型的である。', explanation: '誤り。積乱雲が孤立して点在するまだら状のパターンは、対流性の現象（寒冷前線や不安定な大気の状態）に典型的なパターンであり、温暖前線前面の雲域は、より滑らかで連続的に広がる層状のパターンを示すことが典型的である。' },
      { key: 'D', text: '衛星画像からは温暖前線前面の雲域の広がりを判断することはできない。', explanation: '誤り。衛星画像（可視・赤外画像）はまさに雲域の広がりや形状、雲頂の高さなどを視覚的に把握するための基本的な資料であり、温暖前線前面の雲域の判断に広く活用される。' },
    ],
    correctKey: 'B',
    explanation: '温暖前線前面の雲域は衛星画像上で前線本体よりかなり前方まで滑らかに広がり、前線に近づくにつれ雲頂高度が低くなる（雲頂温度が高くなる）パターンを示す。この広がりから前線の接近度を推測する。\n\n温暖前線の雲域は前線本体の数百 km 前方まで広がり、東へ行くほど雲頂が低く赤外画像では灰色に写る。滑らかで一様な雲域が特徴で、積乱雲が点在するまだら模様にはならない。この広がり方から前線の接近を早い段階で捉えられる。\n\n【図解】温暖前線の雲域の見え方\n　位置｜雲の種類｜赤外画像での見え方\n　前線から遠い前方｜巻雲・巻層雲｜灰色で薄い\n　中間｜高層雲｜やや白い\n　前線付近｜乱層雲｜白く厚い\n　⇒ 雲頂高度が前線に近づくほど高くなる連続的な構造が特徴である\n　⚠ 温暖前線の雲域は滑らかに広がり、孤立した積乱雲が点在する形にはならない。',
    difficulty: 'standard',
    examYear: '令和6年',
