    question: '大雨警報の発表判断における実技的な考え方（判断フロー）に関する記述として正しいものはどれか。',
    choices: [
      { key: 'C', text: '大雨警報の発表判断にあたっては、実況の降水量・土壌雨量指数等の実況資料に加え、今後の降水の見通し（数値予報・降水短時間予報等）を総合的に考慮し、基準となる指数（土壌雨量指数や表面雨量指数等）が警報基準に達する、または達すると予想される場合に、地域の実情も踏まえて発表が判断される。', explanation: '正しい。大雨警報の発表判断は、単純に実況の降水量のみで機械的に決まるものではなく、土壌雨量指数・表面雨量指数など災害発生の危険性をより的確に表す指数の実況値や、数値予報・降水短時間予報等による今後の見通しを総合的に考慮し、基準に達する（または達すると予想される）場合に、地域の地形・過去の災害実績等も踏まえて発表の判断がなされる。' },
      { key: 'B', text: '大雨警報の発表判断は、常に降水量の実況値のみで機械的に自動決定され、今後の見通しは一切考慮されない。', explanation: '誤り。大雨警報の発表判断には、実況値だけでなく今後の降水の見通し（予測）も考慮されており、実況値のみで機械的に決まるものではない。' },
      { key: 'A', text: '大雨警報の基準は全国どの地域でも完全に同一の数値が用いられる。', explanation: '誤り。大雨警報の基準は、地域ごとの地形・地質・過去の災害実績等を踏まえて、市町村ごとに個別の基準値が設定されており、全国一律ではない。' },
      { key: 'D', text: '大雨警報の発表判断には土壌雨量指数などの指数は利用されず、降水量の実測値のみが利用される。', explanation: '誤り。大雨警報の基準には、単純な降水量の実測値だけでなく、土壌への水の蓄積状況を反映した土壌雨量指数など、災害発生の危険性をより的確に表す指数が用いられている。' },
    ],
    correctKey: 'C',
    explanation: '大雨警報の発表判断は、実況の降水量・土壌雨量指数等に今後の予測を組み合わせ、地域ごとに設定された基準への到達可能性を総合的に評価するフローで判断される。\n\n大雨警報の判断では、実況の降水量に加え、表面雨量指数や土壌雨量指数の推移、降水短時間予報による今後の降水見通しを組み合わせる。基準は市町村ごとに設定されており、指数が基準に達すると見込まれる段階で発表する。\n\n【図解】大雨警報の判断材料\n　材料｜内容｜役割\n　実況の降水量｜アメダスと解析雨量｜現在の状況\n　表面雨量指数｜地表を流れる雨水｜浸水害の危険度\n　土壌雨量指数｜土中の水分量｜土砂災害の危険度\n　降水短時間予報｜15時間先まで｜今後の見通し\n　⇒ 実況と予測の両方を突き合わせて発表を判断する\n　⚠ 実況値だけで機械的に決まるのでも、全国一律の基準でもない。',
    difficulty: 'standard',
