    correctKey: 'C',
    explanation: '土砂災害警戒情報の発表判断には、降水の実況・予測から算出される土壌雨量指数が、大雨警報の基準を超えてさらに危険度が高まったことを示す基準線への到達可能性が重要な判断材料となる。\n\n土砂災害警戒情報は、土壌雨量指数と1時間雨量を軸にとったスネーク曲線が、大雨警報の基準を超えて設定された発表基準線に到達すると予想される場合に、気象庁と都道府県が共同で発表する。5 km メッシュ単位で判断される。\n\n【図解】土砂災害警戒情報の判断\n　軸｜指標｜意味\n　縦軸｜土壌雨量指数｜これまでの雨の蓄積\n　横軸｜1時間雨量｜今の降り方の強さ\n　基準線｜過去の災害事例から設定｜到達で発表\n　⇒ 蓄積と強度の両方がそろったときに危険度が最も高まる\n　⚠ 雨が止んだ後に発表される情報ではなく、河川水位で判断するものでもない。',
