    question: '850hPa面の気温分布から前線帯（暖気移流・寒気移流の境界）を解析する方法に関する記述として正しいものはどれか。',
    choices: [
      { key: 'C', text: '850hPa面の等温線が密集している（気温傾度が大きい）帯状の領域は、地表付近の前線帯にほぼ対応することが多く、実技試験ではこの等温線の集中帯の位置・走向を確認することで、地上天気図上の前線の解析（位置の確認・補強）に活用することができる。', explanation: '正しい。850hPa面は地表の摩擦の影響を受けにくい下層の代表的な気圧面であり、この面の等温線が密集している（水平方向の気温傾度が大きい）帯状の領域は、地表付近の前線帯（気団の境界）にほぼ対応することが多い。実技試験では、850hPa面の等温線の集中帯の位置・走向を確認することで、地上天気図に描かれた前線の位置の妥当性を補強的に確認する手法が用いられる。' },
      { key: 'B', text: '850hPa面の気温分布は前線帯の解析には利用されない。', explanation: '誤り。850hPa面の気温分布（等温線の集中帯）は、まさに前線帯の解析に広く利用される重要な資料である。' },
      { key: 'A', text: '850hPa面の等温線が疎（間隔が広い）である領域が、前線帯に対応する。', explanation: '誤り。逆である。等温線が密集している（間隔が狭い、気温傾度が大きい）領域が前線帯に対応する。等温線が疎な領域は気団内部の、比較的一様な気温分布を示す領域である。' },
      { key: 'D', text: '850hPa面の気温分布から前線帯を解析する手法は、地上天気図の前線解析とは完全に独立しており、両者を関連付けることはない。', explanation: '誤り。850hPa面の気温分布による前線帯の解析は、地上天気図の前線解析を補強・確認するために組み合わせて用いられる手法であり、両者は密接に関連付けて解析される。' },
    ],
    correctKey: 'C',
    explanation: '850hPa面の等温線が密集する帯状領域は地表付近の前線帯にほぼ対応する。実技試験ではこの集中帯の位置・走向から地上天気図の前線解析を補強的に確認する。\n\n850 hPa 面で等温線が密集する帯は地上の前線帯に対応し、その南縁付近が地上前線の位置の目安になる。等温線の集中帯と地上の風の不連続、湿域の分布を重ね合わせることで前線解析の精度が上がる。相当温位の集中帯も同様に使われる。\n\n【図解】850 hPa で見る前線帯\n　着眼点｜見え方｜地上との対応\n　等温線の集中帯｜線が密集｜前線帯に対応\n　集中帯の南縁｜温度傾度の南端｜地上前線の目安\n　相当温位の集中帯｜暖湿気の境界｜梅雨前線に有効\n　⇒ 上層の温度場と地上の解析を突き合わせて精度を高める\n　⚠ 等温線が疎な領域は前線帯ではない。密集帯が前線帯に対応する。',
    difficulty: 'standard',
    examYear: '令和4年',
