    choices: [
      { key: 'C', text: '700hPa面の湿数（気温と露点温度の差）が小さい（湿潤な）領域は、中層に十分な水蒸気が存在することを示し、この領域に上昇流が重なると、雲の発生・発達や降水の可能性が高いと判断される。逆に湿数が大きい（乾燥した）領域では、上昇流があっても顕著な雲・降水にはつながりにくい。', explanation: '正しい。700hPa面の湿数（気温と露点温度の差）は中層の湿り具合を示す指標であり、湿数が小さい（気温と露点温度が近い、湿潤な）領域は水蒸気が豊富にあることを示す。この湿潤な領域に上昇流が重なると、水蒸気が持ち上げられて凝結し、雲の発生・発達や降水につながりやすいと判断される。一方、湿数が大きい（乾燥した）領域では、上昇流があっても水蒸気が不足しているため、顕著な雲・降水にはつながりにくい。' },
      { key: 'B', text: '700hPa面の湿数が大きい（乾燥した）領域ほど、雲の発生・発達の可能性が高いと判断される。', explanation: '誤り。逆である。湿数が大きい（乾燥した）領域では、水蒸気が不足しているため雲の発生・発達の可能性は低いと判断される。湿数が小さい（湿潤な）領域ほど可能性が高い。' },
      { key: 'A', text: '700hPa面の湿数の情報だけで、上昇流の有無にかかわらず、降水の有無を確実に判定できる。', explanation: '誤り。湿数（湿り具合）だけでは降水の有無を確実に判定することはできず、上昇流の有無・強さと組み合わせて総合的に評価する必要がある（湿潤でも上昇流がなければ降水にはつながりにくい）。' },
      { key: 'D', text: '700hPa面の湿数は、地上の気温には影響を与える指標だが、雲や降水とは無関係である。', explanation: '誤り。700hPa面の湿数はまさに中層の湿り具合（水蒸気量）を表す指標であり、雲の発生・発達や降水の可能性の評価に直接関連する重要な情報である。' },
    ],
    correctKey: 'C',
    explanation: '700hPa面の湿数が小さい（湿潤な）領域に上昇流が重なると雲・降水の可能性が高まり、湿数が大きい（乾燥した）領域では上昇流があっても顕著な雲・降水にはつながりにくい。\n\n700 hPa の湿数が小さい領域は中層に水蒸気が豊富であることを示すが、上昇流がなければ雲は発達しない。湿域と上昇流域の重なりを見ることが要点で、乾燥した領域では上昇流があっても顕著な降水にはなりにくい。\n\n【図解】湿数と鉛直流の組み合わせ\n　湿数｜鉛直流｜予想される天気\n　小さい（湿域）｜上昇流｜降水の可能性が高い\n　小さい（湿域）｜下降流｜次第に雲が消える\n　大きい（乾域）｜上昇流｜雲はできにくい\n　大きい（乾域）｜下降流｜晴天\n　⇒ 湿りと上昇流の両方がそろって初めて降水になる\n　⚠ 湿数が大きいほど雲ができやすいとするのは逆である。',
