    question: '500hPa面のトラフ（気圧の谷）を実況天気図から解析する方法に関する記述として正しいものはどれか。',
    choices: [
      { key: 'C', text: '500hPa面のトラフは、等高度線が低緯度側へ凹んで（南に張り出して）いる部分として天気図上に現れ、実技試験では、このトラフの深まり具合（等高度線の凹みの大きさ）や移動速度を、連続する時刻の高層天気図から追跡することで、地上の低気圧の発達可能性を評価する手がかりとする。', explanation: '正しい。500hPa面のトラフ（気圧の谷）は、等高度線が低緯度側（南側、北半球の場合）へ凹んで（南に張り出して）いる部分として天気図上に表現される。実技試験では、連続する時刻の500hPa高層天気図を比較し、トラフの深まり具合（凹みの大きさ）や移動速度、トラフ前面（東側）の状況を確認することで、地上の低気圧が今後発達する可能性があるかどうかを評価する手がかりとする。' },
      { key: 'B', text: '500hPa面のトラフは、等高度線が高緯度側へ凹んでいる部分として現れる。', explanation: '誤り。トラフは等高度線が低緯度側（南側）へ凹んでいる部分として現れる。高緯度側へ張り出している部分はリッジ（気圧の尾根）である。' },
      { key: 'A', text: '500hPa面のトラフは、常に地上の前線の位置と完全に一致する。', explanation: '誤り。500hPa面のトラフと地上の前線は関連しつつも、必ずしも完全に一致する位置関係にあるわけではなく、トラフは前線よりもやや西側に位置することが多いなど、両者の位置関係を確認することが実技解析のポイントとなる。' },
      { key: 'D', text: '500hPa面のトラフの深まり具合は、地上の低気圧の発達予測には利用されない。', explanation: '誤り。500hPa面のトラフの深まり具合（等高度線の凹みの大きさ）は、地上の低気圧の発達（傾圧不安定の強さ等）を予測する上で重要な情報として利用される。' },
    ],
    correctKey: 'C',
    explanation: '500hPa面のトラフは等高度線が低緯度側へ凹んでいる部分として現れる。連続する天気図でトラフの深まり具合・移動速度を追跡することで、地上低気圧の発達可能性を評価する。\n\nトラフは等高度線が低緯度側へ張り出した部分で、その軸を実線で示す。連続する天気図でトラフの深まりと東進速度を追い、正渦度移流の強さと合わせて地上低気圧の発達を判断する。トラフの位置は地上前線と一致するとは限らない。\n\n【図解】トラフ解析の着眼点\n　着眼点｜見え方｜判断\n　等高度線の張り出し｜低緯度側へ凹む｜トラフ軸\n　深まり｜張り出しが大きくなる｜低気圧の発達\n　移動速度｜連続図で追跡｜今後の位置\n　⇒ トラフの前面が正渦度移流の領域にあたる\n　⚠ トラフは低緯度側へ凹む部分であり、地上前線の位置と一致するとは限らない。',
