    correctKey: 'C',
    explanation: '寒冷渦は上層天気図で明瞭な閉じた低気圧性循環と寒気を伴うが、地上での対応は不明瞭なことが多い。上層・地上両方の天気図を照らし合わせて確認することが実況判断の要点。\n\n寒冷渦は偏西風帯から切り離された低気圧で、動きが遅く同じ地域に数日居座ることがある。上空に強い寒気を伴うため気温減率が大きくなり、日射による地表加熱が加わると午後に積乱雲が発達して大気の状態が不安定になる。\n\n【図解】寒冷渦の特徴\n　項目｜内容｜結果\n　上層天気図｜閉じた等高度線と寒気｜明瞭に確認できる\n　地上天気図｜対応が不明瞭｜低気圧が弱いことも\n　移動｜遅く停滞しやすい｜影響が長引く\n　天気｜午後に対流雲が発達｜雷雨や突風\n　⇒ 上層と地上の両方を照らし合わせて確認する\n　⚠ 寒冷渦の付近では大気は不安定化する。安定化するとするのは逆である。',
    difficulty: 'standard',
