    correctKey: 'C',
    explanation: '二つ玉低気圧は日本海低気圧と南岸低気圧が同時に発達・進行する型で、両者に挟まれた本州付近で等圧線が集中し、全国的な暴風・大雨に警戒が必要な実技試験で重視される危険パターン。\n\n二つ玉低気圧は日本海と南岸に低気圧が並ぶ型で、両者にはさまれた本州付近では気圧の谷となり等圧線が混んで暴風になりやすい。低気圧が発達しながら東進するため広範囲で荒天となり、春や秋の嵐の典型的なパターンである。\n\n【図解】二つ玉低気圧の危険性\n　場所｜状況｜天気\n　日本海側｜日本海低気圧｜南風が強まりフェーンや融雪\n　本州付近｜気圧の谷｜等圧線が混み暴風\n　太平洋側｜南岸低気圧｜大雨や大雪\n　⇒ 全国的に荒天となるため広域の警戒が必要である\n　⚠ 二つ玉低気圧は温帯低気圧の型であり、間にはさまれた地域が晴れるわけではない。',
