    correctKey: 'C',
    explanation: '南岸低気圧による降雪判断は地上気温だけでなく850hPa気温（寒気の強さ）・湿球温度・低気圧の進路（陸地に近すぎると雨、離れすぎると降水なし）を総合評価する、実技上微妙な判断が求められるテーマ。\n\n南岸低気圧の雨雪判別は実技で最も難しいテーマの一つである。地上気温だけでなく、850 hPa の気温、地上の湿球温度、1000〜500 hPa 層厚、低気圧の進路を総合して判断する。進路が陸に近すぎると暖気が入って雨、離れすぎると降水域が届かない。\n\n【図解】南岸低気圧の雪判断の指標\n　指標｜雪になりやすい条件｜補足\n　850 hPa 気温｜−3 ℃ 以下｜寒気の強さ\n　地上の湿球温度｜1 ℃ 以下｜蒸発冷却を考慮\n　1000〜500 hPa 層厚｜5400 m 以下｜気層全体の寒さ\n　低気圧の進路｜八丈島の北を通ると雨寄り｜経路が鍵\n　⇒ 気温だけでなく湿度も効くため湿球温度が有効である\n　⚠ 進路が南に離れすぎると降水域が届かず、降雪の可能性はむしろ下がる。',
    difficulty: 'standard',
