    question: '移動性高気圧接近時の霧（放射霧）の発生を実況資料から予測する方法に関する記述として正しいものはどれか。',
    choices: [
      { key: 'C', text: '移動性高気圧に覆われ、夜間から早朝にかけて晴天・弱風が予想される場合、放射冷却が進みやすく、湿度が高い状態と組み合わさることで、盆地や内陸の平野部を中心に放射霧が発生する可能性が高いと判断できる。', explanation: '正しい。移動性高気圧に覆われると、雲が少なく風も弱い夜間が予想されやすいため、地表面からの放射冷却が効率よく進み、接地気層の気温が露点温度に近づきやすくなる。特に湿度が高い状態（前日までの降水の影響等）と組み合わさると、盆地や内陸の平野部を中心に放射霧が発生する可能性が高いと、実技試験でも判断される。' },
      { key: 'B', text: '移動性高気圧接近時は、雲量が多く風が強いため、放射霧は発生しにくい。', explanation: '誤り。移動性高気圧に覆われる時期は、一般に雲量が少なく（晴天）、風も弱いことが多く、これはむしろ放射霧が発生しやすい条件である。' },
      { key: 'A', text: '放射霧の発生予測には、湿度（水蒸気量）の情報は不要である。', explanation: '誤り。放射霧は接地気層の気温が露点温度以下に下がることで発生するため、湿度（露点温度）の情報は放射霧の発生予測に不可欠な要素である。' },
      { key: 'D', text: '放射霧は海上でのみ発生し、内陸では発生しない。', explanation: '誤り。放射霧は主に盆地や内陸の平野部で、地表面からの放射冷却によって発生しやすい霧であり、海上でのみ発生するというのは誤りである（海上で見られやすいのは主に移流霧である）。' },
    ],
    correctKey: 'C',
    explanation: '移動性高気圧に覆われる晴天・弱風の夜間は放射冷却が進みやすく、湿度が高い条件と重なると盆地・内陸で放射霧が発生しやすい。実技試験ではこの気象条件の組み合わせを確認する。\n\n放射霧は晴天で風が弱く、湿度が高い夜間から明け方に、内陸の盆地や河川沿いで発生しやすい。移動性高気圧に覆われた夜はこの条件がそろう。前日に降雨があって地面が湿っていると発生しやすさが増す。\n\n【図解】放射霧の発生条件\n　条件｜必要な状態｜理由\n　雲量｜少ない（晴天）｜放射冷却が進む\n　風｜弱い（2 m/s 前後）｜適度な混合\n　湿度｜高い｜飽和に達しやすい\n　地形｜盆地や谷｜冷気が溜まる\n　⇒ 移動性高気圧に覆われた夜は条件がそろいやすい\n　⚠ 放射霧は内陸で発生しやすく、湿度の情報は判断に不可欠である。',
    difficulty: 'standard',
