    correctKey: 'C',
    explanation: 'フェーン現象による高温の実況判断には、風上側の山岳地帯での降水の有無、対象地域の風向（山越えの風かどうか）、急激な気温上昇と湿度低下の同時発生を確認することが重要である。\n\nフェーンでは気温上昇と湿度低下が同時に起こるのが特徴である。実況では、風上側の山地で降水があるか、対象地域の風向が山を越えてくる向きか、気温が急上昇し相対湿度が急低下しているかを確認する。日本海側で南風が吹く場合に多い。\n\n【図解】フェーン発生時の実況の特徴\n　要素｜変化｜確認する資料\n　気温｜急上昇｜アメダス時系列\n　湿度｜急低下｜アメダス時系列\n　風向｜山越えの向き｜地上観測\n　風上側｜降水がある｜レーダー\n　⇒ 気温上昇と湿度低下が同時に起こる点が決め手になる\n　⚠ フェーンでは湿度は下がる。上昇を伴うとするのは誤りである。',
