    explanation: '下層の逆転層・不安定層・上空の沈降性逆転層（キャップ）が重なる複合構造では、日射加熱でCAPEが蓄積されつつキャップに抑えられ、キャップが破られると急激な積乱雲の発達につながる。\n【図解】\n★ポイント: 下層逆転層＋不安定層＋上空キャップ（沈降性逆転層）の複合構造＝エネルギー蓄積型の危険パターン\n○正: Aの通り、キャップが破られると蓄積されたCAPEが一気に解放され急激な積乱雲発達に至る\n×誤: Bのように各層を独立とする記述、Cのようにキャップ存在時は警戒不要とする記述、Dのように出題対象外とする記述はいずれも誤り\n⚠注意: 「静けさの中の危険」＝キャップ存在下でのエネルギー蓄積は防災上むしろ警戒すべき状態\n→ 結論: 複数安定層の複合的な読み取り方を正確に述べたAが正解（A）',
