    question: 'ホドグラフ（高度ごとの風のベクトルをプロットした図）から鉛直シアーやストームの移動方向を評価する方法に関する記述として正しいものはどれか。',
    choices: [
      { key: 'D', text: 'ホドグラフ上で下層から上層にかけての風のベクトルの先端を結んだ曲線の長さ・曲がり方から、鉛直シアーの大きさや、風向が高度とともにどのように変化していくか（時計回りに回転する場合は暖気移流を示唆する等）を評価することができ、曲線の曲率が大きい（強く曲がっている）場合はスーパーセルの発生に有利な環境であることが示唆される。', explanation: '正しい。ホドグラフは各高度の風のベクトルを1つの図上にプロットし、それらの先端を結んだ曲線として表現したものであり、曲線の長さは鉛直シアーの大きさを、曲線の曲がり方（時計回り・反時計回り）は温度風の関係を通じた気温移流の向きを示唆する。特に、下層のホドグラフが強く時計回りに曲がっている（曲率が大きい）場合は、下層の鉛直シアーが強く、これはスーパーセル（持続的な回転を伴う積乱雲）の発生に有利な環境であることを示唆する、実技上重要な着眼点である。' },
      { key: 'B', text: 'ホドグラフは気温の鉛直分布を表す図であり、風の情報は含まれない。', explanation: '誤り。ホドグラフはまさに風（風向風速）の鉛直分布をベクトルとして表現した図であり、気温の鉛直分布を表すものではない（気温の鉛直分布はエマグラムで表現される）。' },
      { key: 'C', text: 'ホドグラフの曲線の曲率は、大気の安定度（CAPE・CIN）と全く同じ情報を表す。', explanation: '誤り。ホドグラフの曲率は風の鉛直シアーに関する情報を表すものであり、CAPE・CIN（気温・水蒸気に基づく安定度・浮力に関する情報）とは異なる、補完的な情報である。両者を組み合わせて評価することが実技上重要である。' },
      { key: 'A', text: 'ホドグラフからは、対流性のストーム（積乱雲）の移動方向を推定することはできない。', explanation: '誤り。ホドグラフの形状（各高度の風のベクトル）から、ストーム相対風（ストームの移動を考慮した相対的な風）の評価を通じて、対流性のストームの予想される移動方向を推定する手法が実技的に用いられる。' },
    ],
    correctKey: 'D',
    explanation: 'ホドグラフは各高度の風ベクトルを結んだ曲線で鉛直シアーの大きさと気温移流の向きを示す。下層で強く時計回りに曲がる（曲率が大きい）ホドグラフはスーパーセル発生に有利な環境を示唆する。\n\nホドグラフは各高度の風ベクトルの先端を結んだ曲線で、線の長さが鉛直シアーの大きさ、曲がり方が風向の変化を表す。下層で時計回りに大きく曲がるホドグラフは暖気移流とストームリラティブヘリシティの大きさを意味し、スーパーセルに有利である。\n\n【図解】ホドグラフの読み取り\n　特徴｜示すもの｜示唆される現象\n　線が長い｜鉛直シアーが大きい｜組織化した対流\n　時計回りに曲がる｜暖気移流｜スーパーセルに有利\n　反時計回りに曲がる｜寒気移流｜―\n　下層の曲率が大きい｜低層のヘリシティ大｜竜巻の可能性\n　⇒ 風の情報だけを扱う図であり、安定度とは別の情報である\n　⚠ ホドグラフは風の図であって気温の鉛直分布を示す図ではない。',
