    explanation: '竜巻発生確度ナウキャストは的中率に限界があるが、竜巻の被害の重大性を踏まえ、発生確度2の発表時には頑丈な建物への避難や窓からの離隔など、安全側に立った具体的行動を直ちに呼びかけることが実技的に適切。\n\n竜巻は適中率が低い一方で被害が甚大なので、発生確度2が出た段階で頑丈な建物へ移動する、窓から離れる、屋外の活動を中止するといった具体的な行動を促すのが適切である。屋内でも窓のない部屋へ移るなどの対応が求められる。\n\n【図解】竜巻接近時の行動\n　場所｜とるべき行動｜避けるべきこと\n　屋外｜頑丈な建物へ移動｜物置やプレハブに入る\n　屋内｜窓から離れ低い階へ｜窓のそばにいる\n　車内｜建物へ避難｜橋の下に停車\n　⇒ 適中率は低くても被害の重大性から安全側の行動が求められる\n　⚠ 有効期間は1時間程度であり、1週間先を示す情報ではない。',
