    correctKey: 'D',
    explanation: '台風の急速強化の判断には、衛星画像での構造変化（眼の明瞭化・眼壁の組織化）と、海面水温（暖水層の深さ）・鉛直シアーの強さといった環境条件を組み合わせて総合的に評価する。\n\n急速強化の兆候は、衛星画像で眼が明瞭化し眼の壁雲が同心円状に整うことである。あわせて進路上の海面水温と暖水層の厚さ、鉛直シアーの弱さ、上層のアウトフローの良好さを確認する。これらの環境条件がそろうと発達が加速する。\n\n【図解】急速強化の判断材料\n　資料｜着眼点｜好条件\n　衛星画像｜眼と壁雲の構造｜明瞭化し対称化\n　海洋データ｜海面水温と暖水層｜高温で厚い\n　解析図｜鉛直シアー｜弱い\n　上層天気図｜アウトフロー｜良好な発散\n　⇒ 構造の変化と環境条件を組み合わせて判断する\n　⚠ 鉛直シアーが強いほど強化しやすいとするのは逆で、強いと構造が崩れる。',
    difficulty: 'advanced',
