    correctKey: 'D',
    explanation: '温帯低気圧化の過程では地上天気図の対称的な等圧線が非対称化し前線（主に寒冷前線）が明瞭になり、衛星画像でも対称的な雲域が前線に沿った帯状の非対称構造へ変化する。\n\n温帯低気圧化の過程では、地上天気図で等圧線が非対称になり寒冷前線が明瞭に解析されるようになる。衛星画像でも同心円状の雲域が崩れ、前線に沿った帯状の雲や乾燥した暗域の入り込みが見られる。両方を合わせて判断する。\n\n【図解】温帯低気圧化の兆候\n　資料｜台風のとき｜温帯低気圧化の過程\n　地上天気図｜等圧線が同心円状｜非対称化し前線が出現\n　衛星画像｜対称的な渦｜前線に沿う帯状の雲\n　水蒸気画像｜―｜乾燥暗域の入り込み\n　⇒ 構造の非対称化と前線の出現が判断の決め手になる\n　⚠ 温帯低気圧化した後こそ前線が解析される。解析されなくなるのではない。',
