    choices: [
      { key: 'D', text: '乾燥注意報の発表判断では、実効湿度（過去数日間の湿度の推移を考慮した、火災の延焼しやすさに関わる指標）や最小湿度の予測値を確認するとともに、フェーン現象等により一時的に湿度が急激に低下する可能性がある場合には、その影響も踏まえて総合的に危険性を評価することが重要である。', explanation: '正しい。乾燥注意報の発表判断には、単純なその日の最小湿度だけでなく、過去数日間の湿度の推移を反映した実効湿度（乾燥した状態がどれだけ持続しているかを示す指標で、火災の延焼のしやすさと関連する）を確認することが基本となる。あわせて、フェーン現象等により一時的に湿度が急激に低下する可能性がある場合には、その影響も踏まえて、火災発生・延焼の危険性を総合的に評価することが実技上重要である。' },
      { key: 'B', text: '乾燥注意報の発表判断には、実効湿度は用いられず、当日の最小湿度の予測値のみが用いられる。', explanation: '誤り。乾燥注意報の判断には、過去数日間の湿度の推移を反映した実効湿度が重要な指標として用いられており、当日の最小湿度のみで判断されるわけではない。' },
      { key: 'C', text: 'フェーン現象は湿度には影響を与えず、気温にのみ影響する現象である。', explanation: '誤り。フェーン現象は風上側での水蒸気の損失を伴うため、風下側では気温の上昇だけでなく、湿度（相対湿度）の顕著な低下も伴う現象であり、乾燥注意報の判断にも関連する。' },
      { key: 'A', text: '乾燥注意報は火災とは無関係な情報であり、湿度の低さのみを伝える情報である。', explanation: '誤り。乾燥注意報は、空気の乾燥により火災が発生しやすく、また延焼が拡大しやすい気象状況になっていることを伝え、防火への注意を呼びかけることを主な目的とした情報であり、火災と密接に関連する。' },
    ],
    correctKey: 'D',
    explanation: '乾燥注意報の発表判断には実効湿度（過去数日の湿度推移を反映、火災延焼のしやすさに関連）や最小湿度予測に加え、フェーン現象による一時的な湿度急低下の可能性も踏まえた総合評価が重要。\n\n実効湿度は当日の湿度だけでなく前日以前の湿度も重みをつけて加味した指標で、木材の乾き具合すなわち火災の延焼しやすさに対応する。乾燥注意報は実効湿度と最小湿度の基準で発表され、フェーンによる急な湿度低下も判断材料になる。\n\n【図解】乾燥注意報の判断材料\n　指標｜内容｜意味\n　実効湿度｜数日の湿度を加味｜木材の乾燥度\n　最小湿度｜当日の最低値｜その日の乾燥\n　風速｜強いほど危険｜延焼の拡大\n　フェーン｜急な湿度低下｜一時的な危険増大\n　⇒ 火災の延焼しやすさを評価するための情報である\n　⚠ 当日の最小湿度だけで判断するのではなく、実効湿度も用いる。',
    difficulty: 'advanced',
    examYear: '令和6年',
