    choices: [
      { key: 'A', text: '数値予報資料を総合的に読み合わせる際には、まず地上・上層の実況天気図で現在の状態を正確に把握し、次に数値予報の予測資料（地上気圧・降水量・気温等の予想図）で今後の変化の見通しを確認し、さらにエマグラムや安定度指数等の詳細資料で局地的な危険性（対流の可能性等）を評価するという、実況把握から予測、詳細評価へと段階的に読み進める手順が基本となる。', explanation: '正しい。実技試験における数値予報資料の総合的な読み合わせでは、まず地上・上層の実況天気図によって「現在」の大気の状態を正確に把握することが出発点となり、次に数値予報の予測資料（地上気圧・降水量・気温等の予想図）を用いて「今後」の変化の見通しを確認し、さらに必要に応じてエマグラムや安定度指数等のより詳細な資料を用いて、局地的な危険性（対流発生の可能性等）を評価するという、実況把握→予測確認→詳細評価という段階的な読み進め方が、実技試験における基本的な手順とされる。' },
      { key: 'B', text: '数値予報資料の読み合わせでは、まず数値予報の予測資料のみを確認すればよく、実況天気図の確認は不要である。', explanation: '誤り。数値予報の予測結果を正しく解釈するためには、まず現在の実況（実際の大気の状態）を正確に把握することが前提となるため、実況天気図の確認は不可欠な出発点である。' },
      { key: 'C', text: 'エマグラムや安定度指数等の詳細資料は、実技試験の総合問題では扱われない。', explanation: '誤り。エマグラムや安定度指数（SSI、K指数、CAPE等）は、実技試験の総合問題において、局地的な対流の危険性等を評価するための重要な詳細資料として頻繁に扱われる。' },
      { key: 'D', text: '数値予報資料の読み合わせの手順は、試験問題ごとに全く異なり、共通する考え方は存在しない。', explanation: '誤り。実況把握→予測確認→詳細評価という段階的な読み合わせの手順は、多くの実技試験の総合問題に共通する基本的な考え方として位置づけられる。' },
    ],
    correctKey: 'A',
    explanation: '数値予報資料の総合的な読み合わせは、実況天気図による現状把握→予測資料による今後の見通し確認→エマグラム等詳細資料による局地的危険性評価という段階的な手順が実技試験の基本。\n\n資料の読み合わせは、実況で現在を押さえ、予測資料で今後の推移を確認し、エマグラムや安定度指数で局地的な危険性を評価するという段階を踏む。実況を飛ばして予測だけを見ると、モデルの初期値のずれに気づけない。\n\n【図解】資料を読む段階\n　段階｜資料｜わかること\n　1｜地上・高層の実況天気図｜現在の総観場\n　2｜数値予報の予測資料｜今後の推移\n　3｜エマグラム・安定度指数｜局地的な危険性\n　4｜レーダー・衛星｜実況との整合の確認\n　⇒ 実況で現状を押さえてから予測を見るのが基本の順序である\n　⚠ 予測資料だけを見るとモデルの初期値のずれを見落とす危険がある。',
