    correctKey: 'A',
    explanation: '温度移流の判断は、風が等温線を高温側から低温側へ横切れば暖気移流、低温側から高温側へ横切れば寒気移流と判断する、風向と等温線の走向の関係を用いた基本的な解析手法。\n【図解】\n★ポイント: 風が等温線を「高温→低温」へ横切る＝暖気移流、「低温→高温」へ横切る＝寒気移流\n○正: Aの通り、風向と等温線の走向の関係から温度移流の向きを判断するのが実技解析の基本\n×誤: Bのように平行を暖気移流とする記述、Cのように風向不要とする記述、Dのように地上限定とする記述はいずれも誤り\n→ 結論: 温度移流の読み取り方を正確に述べたAが正解（A）',
    difficulty: 'advanced',
