    correctKey: 'A',
    explanation: '上層の正渦度移流域と下層の暖気移流域が鉛直に重なる地域は、両者が相加的に上昇流を強めるため、雲の発達・降水の強化が予想される。上層・下層情報の重ね合わせが実技上の定性判断法。\n\nオメガ方程式の定性的な理解では、上層の正渦度移流と下層の暖気移流がいずれも上昇流を強める。両者が鉛直に重なる領域では効果が足し合わさり、上昇流が最も強くなって雲と降水が発達する。逆に上層の負渦度移流と下層の寒気移流が重なれば下降流となる。\n\n【図解】上昇流を強める組み合わせ\n　上層（500 hPa）｜下層（850 hPa）｜結果\n　正渦度移流｜暖気移流｜上昇流が最大\n　正渦度移流｜寒気移流｜効果が相殺\n　負渦度移流｜寒気移流｜下降流\n　⇒ 二つの資料を重ね合わせて上昇流域を絞り込む\n　⚠ 下層の寒気移流は下降流を強める側であり、上昇流を強めるのではない。',
